// === 温湿度监控 - 历史记录 ===
export interface TempHumHistory {
  id: number;
  areaLocation: string;
  deviceName: string;
  deviceCategory: string;
  product: string;
  attrName: string;
  attrValue: number;
  updateTime: string;
}

// 基于实时数据生成历史记录（每日多点采样）
export const tempHumHistory: TempHumHistory[] = (() => {
  const devices = tempHumDevices;
  const records: TempHumHistory[] = [];
  let id = 1;
  // 每天生成 2 条（温度 + 湿度）记录，共约 57条 设备 x 2 ≈ 114条 记录作为样本
  const sampleDevices = devices.slice(0, 16); // 截图3有16行（一页）
  sampleDevices.forEach((dev) => {
    const tempVariation = Math.round((dev.temperature + (Math.random() * 1.5 - 0.3)) * 10) / 10;
    const humVariation = Math.round((dev.humidity + (Math.random() * 3 - 0.5)) * 10) / 10;
    records.push({
      id: id++,
      areaLocation: dev.areaLocation,
      deviceName: dev.deviceName,
      deviceCategory: dev.deviceCategory,
      product: dev.product,
      attrName: '温度',
      attrValue: tempVariation,
      updateTime: '2026-08-31 11:37:00',
    });
    records.push({
      id: id++,
      areaLocation: dev.areaLocation,
      deviceName: dev.deviceName,
      deviceCategory: dev.deviceCategory,
      product: dev.product,
      attrName: '湿度',
      attrValue: humVariation,
      updateTime: '2026-08-31 11:37:00',
    });
  });
  return records;
})();

// === 温湿度监控 - 数据趋势 ===
export interface TrendDataPoint {
  time: string; // HH:mm
  temperature: number;
  humidity: number;
}

// 基于截图4/5的模拟 24 小时数据，每小时一个点
export const generateTrendData = (deviceName: string): TrendDataPoint[] => {
  // 不同设备用不同基线，这里生成平滑的正弦波趋势
  const baseTemp = 22;
  const baseHum = 68;
  const points: TrendDataPoint[] = [];
  for (let h = 0; h < 24; h++) {
    const temp = Math.round((baseTemp + Math.sin((h / 24) * Math.PI * 2) * 6 + Math.sin(h * 0.4) * 1.2) * 10) / 10;
    const hum = Math.round((baseHum + Math.sin((h / 24) * Math.PI * 2 + 0.5) * 8 + Math.cos(h * 0.3) * 2.5) * 10) / 10;
    const hh = String(h).padStart(2, '0');
    points.push({ time: `${hh}:00`, temperature: temp, humidity: hum });
  }
  return points;
};

