// === 漏水监测 - 历史记录 ===
export interface WaterLeakHistory {
  id: number;
  areaLocation: string;
  deviceName: string;
  deviceCategory: string;
  product: string;
  attrName: string; // 属性名: 漏水状态
  attrValue: string; // 属性值: 正常 / 告警
  updateTime: string;
}

export const waterLeakHistory: WaterLeakHistory[] = (() => {
  const records: WaterLeakHistory[] = [];
  let id = 1;
  waterLeakDevices.forEach((dev) => {
    // 每个设备生成2条历史记录
    records.push({
      id: id++,
      areaLocation: dev.areaLocation,
      deviceName: dev.deviceName,
      deviceCategory: dev.deviceCategory,
      product: dev.product,
      attrName: '漏水状态',
      attrValue: '正常',
      updateTime: '2026-08-31 11:37:00',
    });
    records.push({
      id: id++,
      areaLocation: dev.areaLocation,
      deviceName: dev.deviceName,
      deviceCategory: dev.deviceCategory,
      product: dev.product,
      attrName: '漏水状态',
      attrValue: '正常',
      updateTime: '2026-08-31 10:37:00',
    });
  });
  return records;
})();

// === 漏水监测 - 数据趋势 ===
export interface WaterLeakTrendPoint {
  time: string; // HH:mm
  status: '正常' | '告警'; // 漏水状态
  statusValue: number; // 0=正常, 1=告警 (用于绘图)
}

// 漏水状态趋势数据：24小时，默认全部为正常(0)
export const generateWaterLeakTrendData = (_deviceName: string): WaterLeakTrendPoint[] => {
  const points: WaterLeakTrendPoint[] = [];
  for (let h = 0; h < 24; h++) {
    const hh = String(h).padStart(2, '0');
    points.push({ time: `${hh}:00`, status: '正常', statusValue: 0 });
  }
  return points;
};
