import { useState, useMemo } from 'react';
import { Table, Select, Input, Button, DatePicker, Pagination, Empty } from 'antd';
import dayjs from 'dayjs';
import {
  SearchOutlined,
  ReloadOutlined,
  UnorderedListOutlined,
  AppstoreOutlined,
  ThunderboltOutlined,
  DownloadOutlined,
  DashboardOutlined,
} from '@ant-design/icons';
import {
  tempHumDevices,
  tempHumAreaLocations,
  tempHumHistory,
  generateTrendData,
  TempHumDevice,
  TempHumHistory as TempHumHistoryType,
  TrendDataPoint,
} from '../data/dynamicMonitorData';

type ViewMode = 'list' | 'card';
type TabKey = 'realtime' | 'history' | 'trend';

// === 实时数据 - 表格视图 ===
const RealtimeTable = ({ devices }: { devices: TempHumDevice[] }) => {
  const columns = [
    {
      title: '序号',
      key: 'index',
      width: 60,
      render: (_: unknown, __: unknown, idx: number) => idx + 1,
    },
    { title: '区域位置', dataIndex: 'areaLocation', key: 'areaLocation', sorter: (a: TempHumDevice, b: TempHumDevice) => a.areaLocation.localeCompare(b.areaLocation) },
    { title: '设备名称', dataIndex: 'deviceName', key: 'deviceName', sorter: (a: TempHumDevice, b: TempHumDevice) => a.deviceName.localeCompare(b.deviceName) },
    { title: '设备类别', dataIndex: 'deviceCategory', key: 'deviceCategory' },
    { title: '所属产品', dataIndex: 'product', key: 'product' },
    {
      title: '温度',
      dataIndex: 'temperature',
      key: 'temperature',
      sorter: (a: TempHumDevice, b: TempHumDevice) => a.temperature - b.temperature,
      render: (v: number) => `${v} ℃`,
    },
    {
      title: '湿度',
      dataIndex: 'humidity',
      key: 'humidity',
      sorter: (a: TempHumDevice, b: TempHumDevice) => a.humidity - b.humidity,
      render: (v: number) => `${v} %`,
    },
    { title: '更新时间', dataIndex: 'updateTime', key: 'updateTime', sorter: (a: TempHumDevice, b: TempHumDevice) => a.updateTime.localeCompare(b.updateTime) },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      render: (status: string) => (
        <span
          className={`inline-block px-2 py-0.5 rounded text-xs font-medium ${
            status === 'online'
              ? 'bg-green-50 text-green-600 border border-green-200'
              : 'bg-red-50 text-red-600 border border-red-200'
          }`}
        >
          {status === 'online' ? '已连接' : '离线'}
        </span>
      ),
    },
  ];

  return (
    <Table
      columns={columns}
      dataSource={devices}
      rowKey="id"
      pagination={{ pageSize: 20, showSizeChanger: true, showTotal: (total) => `共 ${total} 条` }}
      size="middle"
      bordered
    />
  );
};

// === 实时数据 - 卡片视图 ===
const RealtimeCards = ({ devices }: { devices: TempHumDevice[] }) => {
  const [page, setPage] = useState(1);
  const pageSize = 20;
  const startIdx = (page - 1) * pageSize;
  const pagedDevices = devices.slice(startIdx, startIdx + pageSize);

  return (
    <div>
      <div className="grid grid-cols-5 gap-4 mb-4">
        {pagedDevices.map((dev) => (
          <div
            key={dev.id}
            className="bg-white rounded-lg border border-gray-200 p-4 hover:shadow-md transition-shadow"
          >
            <div className="flex items-start justify-between mb-3">
              <span className="text-sm font-medium text-gray-800 truncate max-w-[70%]">
                {dev.deviceName}
              </span>
              <span
                className={`inline-flex items-center gap-1 px-2 py-0.5 rounded text-[11px] font-medium whitespace-nowrap ${
                  dev.status === 'online'
                    ? 'bg-green-50 text-green-600 border border-green-200'
                    : 'bg-red-50 text-red-600 border border-red-200'
                }`}
              >
                <span className={`w-1.5 h-1.5 rounded-full ${dev.status === 'online' ? 'bg-green-500' : 'bg-red-500'}`}></span>
                {dev.status === 'online' ? '已连接' : '离线'}
              </span>
            </div>
            <div className="flex items-center justify-between text-xs text-gray-600">
              <div className="flex items-center gap-1">
                <span className="text-blue-500">💧</span>
                湿度(<span className="font-semibold text-blue-600">{dev.humidity}</span>)
              </div>
              <div className="flex items-center gap-1">
                <span className="text-orange-500">🌡️</span>
                温度(℃): <span className="font-semibold text-orange-600">{dev.temperature}</span>
              </div>
            </div>
          </div>
        ))}
      </div>
      <div className="flex justify-end">
        <Pagination
          current={page}
          pageSize={pageSize}
          total={devices.length}
          showSizeChanger={false}
          showTotal={(total) => `共 ${total} 条`}
          onChange={setPage}
        />
      </div>
    </div>
  );
};

// === 历史记录 ===
const HistoryTable = ({ records }: { records: TempHumHistoryType[] }) => {
  const columns = [
    { key: 'index', title: '序号', width: 60, render: (_: unknown, __: unknown, idx: number) => idx + 1 },
    { title: '区域位置', dataIndex: 'areaLocation', key: 'areaLocation', sorter: (a: TempHumHistoryType, b: TempHumHistoryType) => a.areaLocation.localeCompare(b.areaLocation) },
    { title: '设备名称', dataIndex: 'deviceName', key: 'deviceName', sorter: (a: TempHumHistoryType, b: TempHumHistoryType) => a.deviceName.localeCompare(b.deviceName) },
    { title: '设备类别', dataIndex: 'deviceCategory', key: 'deviceCategory' },
    { title: '所属产品', dataIndex: 'product', key: 'product' },
    { title: '属性名', dataIndex: 'attrName', key: 'attrName' },
    {
      title: '属性值',
      dataIndex: 'attrValue',
      key: 'attrValue',
      sorter: (a: TempHumHistoryType, b: TempHumHistoryType) => a.attrValue - b.attrValue,
      render: (v: number, record: TempHumHistoryType) =>
        record.attrName === '温度' ? `${v}` : `${v}`,
    },
    { title: '更新时间', dataIndex: 'updateTime', key: 'updateTime', sorter: (a: TempHumHistoryType, b: TempHumHistoryType) => a.updateTime.localeCompare(b.updateTime) },
  ];

  return (
    <Table
      columns={columns}
      dataSource={records}
      rowKey="id"
      pagination={{
        pageSize: 20,
        showSizeChanger: true,
        showTotal: (total) => `共 ${total} 条`,
      }}
      size="middle"
      bordered
    />
  );
};

// === 趋势图 (SVG Line Chart) ===
const TrendChart = ({ data }: { data: TrendDataPoint[] }) => {
  const [showTemp, setShowTemp] = useState(true);
  const [showHum, setShowHum] = useState(true);

  const width = 1000;
  const height = 420;
  const padding = { top: 30, right: 30, bottom: 60, left: 50 };
  const innerW = width - padding.left - padding.right;
  const innerH = height - padding.top - padding.bottom;

  // 计算 Y 轴范围 (湿度和温度在同一坐标, 温度 ~12-32, 湿度 ~40-90)
  // 温度用左侧轴, 湿度用右侧轴
  const tempMin = 0, tempMax = 70; // 让温度线也落到 0-70 轴范围以贴合截图布局（截图有双线）
  const humMin = 0, humMax = 100;

  const xStep = innerW / (data.length - 1);
  const xOf = (i: number) => padding.left + i * xStep;

  const yTemp = (v: number) => padding.top + innerH - ((v - tempMin) / (tempMax - tempMin)) * innerH;
  const yHum = (v: number) => padding.top + innerH - ((v - humMin) / (humMax - humMin)) * innerH;

  // Y轴刻度
  const yTicks = [0, 10, 20, 30, 40, 50, 60, 70];

  const tempPath = data.map((d, i) => `${i === 0 ? 'M' : 'L'} ${xOf(i)} ${yTemp(d.temperature)}`).join(' ');
  const humPath = data.map((d, i) => `${i === 0 ? 'M' : 'L'} ${xOf(i)} ${yHum(d.humidity)}`).join(' ');

  // X轴刻度 (每2小时)
  const xTickIdx = data.filter((_, i) => i % 2 === 0).map((_, i) => i * 2);

  return (
    <div className="bg-white rounded-lg border border-gray-200 p-6">
      {/* Legend */}
      <div className="flex items-center gap-6 mb-4">
        <label className="flex items-center gap-2 cursor-pointer text-sm text-gray-700" onClick={() => setShowTemp((s) => !s)}>
          <input type="checkbox" checked={showTemp} onChange={(e) => setShowTemp(e.target.checked)} className="accent-blue-500" />
          <span className="inline-block w-3 h-[2px] bg-green-500"></span>
          温度
        </label>
        <label className="flex items-center gap-2 cursor-pointer text-sm text-gray-700" onClick={() => setShowHum((s) => !s)}>
          <input type="checkbox" checked={showHum} onChange={(e) => setShowHum(e.target.checked)} className="accent-blue-500" />
          <span className="inline-block w-3 h-[2px] bg-blue-500"></span>
          湿度
        </label>
      </div>

      <div className="overflow-x-auto">
        <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-auto min-w-[800px]">
          {/* 背景网格线 - 水平 */}
          {yTicks.map((t) => (
            <g key={`yt-${t}`}>
              <line
                x1={padding.left}
                y1={padding.top + innerH - (t / 70) * innerH}
                x2={padding.left + innerW}
                y2={padding.top + innerH - (t / 70) * innerH}
                stroke="#e5e7eb"
                strokeDasharray="3,3"
              />
              <text
                x={padding.left - 8}
                y={padding.top + innerH - (t / 70) * innerH + 4}
                textAnchor="end"
                fontSize="11"
                fill="#9ca3af"
              >
                {t}
              </text>
            </g>
          ))}

          {/* X轴 */}
          <line x1={padding.left} y1={padding.top + innerH} x2={padding.left + innerW} y2={padding.top + innerH} stroke="#d1d5db" />
          {xTickIdx.map((i) => {
            const d = data[i];
            if (!d) return null;
            return (
              <g key={`xt-${i}`}>
                <line x1={xOf(i)} y1={padding.top + innerH} x2={xOf(i)} y2={padding.top + innerH + 4} stroke="#d1d5db" />
                <text x={xOf(i)} y={padding.top + innerH + 18} textAnchor="middle" fontSize="11" fill="#6b7280">
                  {d.time}
                </text>
              </g>
            );
          })}

          {/* 温度线 */}
          {showTemp && (
            <g>
              <path d={tempPath} fill="none" stroke="#22c55e" strokeWidth="2" />
              {data.map((d, i) => (
                <circle key={`td-${i}`} cx={xOf(i)} cy={yTemp(d.temperature)} r="3" fill="#22c55e" />
              ))}
            </g>
          )}

          {/* 湿度线 */}
          {showHum && (
            <g>
              <path d={humPath} fill="none" stroke="#3b82f6" strokeWidth="2" />
              {data.map((d, i) => (
                <circle key={`hd-${i}`} cx={xOf(i)} cy={yHum(d.humidity)} r="3" fill="#3b82f6" />
              ))}
            </g>
          )}
        </svg>
      </div>

      {/* Mini range preview (screenshot 4 has this below the chart) */}
      <div className="mt-4 h-12 bg-gray-50 rounded border border-gray-200 relative">
        <div className="absolute left-[10%] right-[5%] top-1 bottom-1 bg-blue-100/50 border border-blue-300 rounded">
          <div className="absolute left-0 top-0 bottom-0 w-1 bg-blue-500 rounded-l"></div>
          <div className="absolute right-0 top-0 bottom-0 w-1 bg-blue-500 rounded-r"></div>
        </div>
      </div>
    </div>
  );
};

// === 主组件 ===
const TempHumMonitor = () => {
  const [tab, setTab] = useState<TabKey>('realtime');
  const [viewMode, setViewMode] = useState<ViewMode>('list');

  // Realtime filters
  const [rtArea, setRtArea] = useState<string | undefined>(undefined);
  const [rtDevice, setRtDevice] = useState('');

  // History filters
  const [hisArea, setHisArea] = useState<string | undefined>(undefined);
  const [hisDevice, setHisDevice] = useState('');
  const [hisRange, setHisRange] = useState<dayjs.Dayjs | null>(null);

  // Trend filters
  const [trendDevice, setTrendDevice] = useState<string>(tempHumDevices[0].deviceName);
  const [trendDate, setTrendDate] = useState<dayjs.Dayjs>(dayjs('2026-08-31'));

  const filteredRealtime = useMemo(() => {
    return tempHumDevices.filter((d) => {
      if (rtArea && d.areaLocation !== rtArea) return false;
      if (rtDevice && !d.deviceName.toLowerCase().includes(rtDevice.toLowerCase())) return false;
      return true;
    });
  }, [rtArea, rtDevice]);

  const filteredHistory = useMemo(() => {
    return tempHumHistory.filter((d) => {
      if (hisArea && d.areaLocation !== hisArea) return false;
      if (hisDevice && !d.deviceName.toLowerCase().includes(hisDevice.toLowerCase())) return false;
      return true;
    });
  }, [hisArea, hisDevice]);

  const trendData = useMemo(() => generateTrendData(trendDevice), [trendDevice]);

  const resetRealtime = () => {
    setRtArea(undefined);
    setRtDevice('');
  };
  const resetHistory = () => {
    setHisArea(undefined);
    setHisDevice('');
    setHisRange(null);
  };
  const resetTrend = () => {
    setTrendDevice(tempHumDevices[0].deviceName);
    setTrendDate(dayjs('2026-08-31'));
  };

  return (
    <div className="bg-gray-50 min-h-full">
      {/* Top bar (title area) */}
      <div className="bg-white border-b border-gray-200 px-6 py-3">
        <div className="flex items-center gap-2 text-sm text-gray-500 mb-2">
          <span>动环监测</span>
          <span>/</span>
          <span className="text-gray-800 font-medium">温湿度监控</span>
        </div>
      </div>

      <div className="p-6">
        {/* Tabs */}
        <div className="bg-white rounded-lg border border-gray-200 mb-4">
          <div className="flex border-b border-gray-200 px-4 pt-3">
            {[
              { key: 'realtime', label: '实时数据', icon: <ThunderboltOutlined /> },
              { key: 'history', label: '历史记录', icon: <UnorderedListOutlined /> },
              { key: 'trend', label: '数据趋势', icon: <DashboardOutlined /> },
            ].map((t) => (
              <div
                key={t.key}
                className={`px-4 py-2.5 cursor-pointer text-sm transition-colors relative ${
                  tab === t.key ? 'text-blue-600 font-medium' : 'text-gray-600 hover:text-gray-800'
                }`}
                onClick={() => setTab(t.key as TabKey)}
              >
                <span className="mr-1.5">{t.icon}</span>
                {t.label}
                {tab === t.key && (
                  <div className="absolute bottom-0 left-0 right-0 h-[2px] bg-blue-600 rounded-t"></div>
                )}
              </div>
            ))}
          </div>

          {/* Filters & Action bar */}
          <div className="px-4 py-3 border-b border-gray-100">
            {tab === 'realtime' && (
              <div className="flex items-center gap-3 flex-wrap">
                <span className="text-sm text-gray-600">区域位置:</span>
                <Select
                  allowClear
                  placeholder="请选择"
                  style={{ width: 180 }}
                  value={rtArea}
                  onChange={(v) => setRtArea(v)}
                  options={tempHumAreaLocations.map((a) => ({ label: a, value: a }))}
                />
                <span className="text-sm text-gray-600 ml-2">设备名称:</span>
                <Input
                  placeholder="请输入"
                  style={{ width: 180 }}
                  value={rtDevice}
                  onChange={(e) => setRtDevice(e.target.value)}
                  allowClear
                />
                <div className="ml-auto flex items-center gap-2">
                  <div className="flex items-center border border-gray-200 rounded overflow-hidden mr-2">
                    <button
                      className={`px-2.5 py-1 text-sm transition-colors ${viewMode === 'list' ? 'bg-blue-50 text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
                      onClick={() => setViewMode('list')}
                      title="列表视图"
                    >
                      <UnorderedListOutlined />
                    </button>
                    <button
                      className={`px-2.5 py-1 text-sm transition-colors border-l border-gray-200 ${viewMode === 'card' ? 'bg-blue-50 text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
                      onClick={() => setViewMode('card')}
                      title="卡片视图"
                    >
                      <AppstoreOutlined />
                    </button>
                  </div>
                  <Button type="primary" icon={<SearchOutlined />}>查询</Button>
                  <Button icon={<ReloadOutlined />} onClick={resetRealtime}>重置</Button>
                </div>
              </div>
            )}

            {tab === 'history' && (
              <div className="flex items-center gap-3 flex-wrap">
                <span className="text-sm text-gray-600">区域位置:</span>
                <Select
                  allowClear
                  placeholder="请选择"
                  style={{ width: 180 }}
                  value={hisArea}
                  onChange={(v) => setHisArea(v)}
                  options={tempHumAreaLocations.map((a) => ({ label: a, value: a }))}
                />
                <span className="text-sm text-gray-600 ml-2">设备名称:</span>
                <Input
                  placeholder="请输入"
                  style={{ width: 180 }}
                  value={hisDevice}
                  onChange={(e) => setHisDevice(e.target.value)}
                  allowClear
                />
                <span className="text-sm text-gray-600 ml-2">统计日期:</span>
                <DatePicker value={hisRange} onChange={(d) => setHisRange(d as dayjs.Dayjs | null)} placeholder="选择日期" />
                <div className="ml-auto flex items-center gap-2">
                  <Button type="primary" icon={<SearchOutlined />}>查询</Button>
                  <Button icon={<ReloadOutlined />} onClick={resetHistory}>重置</Button>
                  <Button icon={<DownloadOutlined />}>导出</Button>
                </div>
              </div>
            )}

            {tab === 'trend' && (
              <div className="flex items-center gap-3 flex-wrap">
                <span className="text-sm text-gray-600">设备名称:</span>
                <Select
                  style={{ width: 240 }}
                  value={trendDevice}
                  onChange={(v) => setTrendDevice(v)}
                  showSearch
                  filterOption={(input, option) =>
                    (option?.label as string).toLowerCase().includes(input.toLowerCase())
                  }
                  options={tempHumDevices.map((d) => ({ label: d.deviceName, value: d.deviceName }))}
                />
                <span className="text-sm text-gray-600 ml-2">数据日期:</span>
                <DatePicker
                  value={trendDate}
                  onChange={(d) => setTrendDate(d as dayjs.Dayjs)}
                  placeholder="选择日期"
                />
                <div className="ml-auto flex items-center gap-2">
                  <Button type="primary" icon={<SearchOutlined />}>查询</Button>
                  <Button icon={<ReloadOutlined />} onClick={resetTrend}>重置</Button>
                </div>
              </div>
            )}
          </div>

          {/* Tab Content */}
          <div className="p-4">
            {tab === 'realtime' && (
              filteredRealtime.length === 0 ? (
                <Empty description="暂无数据" />
              ) : viewMode === 'list' ? (
                <RealtimeTable devices={filteredRealtime} />
              ) : (
                <RealtimeCards devices={filteredRealtime} />
              )
            )}

            {tab === 'history' && (
              filteredHistory.length === 0 ? (
                <Empty description="暂无数据" />
              ) : (
                <HistoryTable records={filteredHistory} />
              )
            )}

            {tab === 'trend' && (
              <TrendChart data={trendData} />
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TempHumMonitor;
