import { useState, useEffect } from 'react';
import { Input } from 'antd';
import { SearchOutlined, BellOutlined, UserOutlined } from '@ant-design/icons';
import { commonApps, taskStats, topNavTabs } from '../data/workbenchData';

interface WorkbenchProps {
  onNavigate: (route: string) => void;
}

const Workbench = ({ onNavigate }: WorkbenchProps) => {
  const [activeTab, setActiveTab] = useState('workbench');
  const [currentTime, setCurrentTime] = useState(new Date());
  const [searchValue, setSearchValue] = useState('');

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const formatDate = (date: Date) => {
    const days = ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六'];
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    const h = String(date.getHours()).padStart(2, '0');
    const mi = String(date.getMinutes()).padStart(2, '0');
    const s = String(date.getSeconds()).padStart(2, '0');
    return {
      dateStr: `今天是${y}年${m}月${d}日，${days[date.getDay()]}`,
      timeStr: `${h}:${mi}:${s}`,
    };
  };

  const { dateStr, timeStr } = formatDate(currentTime);

  const handleAppClick = (app: typeof commonApps[0]) => {
    if (app.url) {
      window.open(app.url, '_blank');
    } else if (app.internalRoute) {
      onNavigate(app.internalRoute);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col">
      {/* Top Navigation */}
      <header className="h-14 bg-white border-b border-gray-200 flex items-center px-6 relative z-10">
        {/* Hamburger */}
        <div className="flex items-center gap-4 mr-8">
          <div className="w-6 h-6 flex flex-col justify-center gap-[3px] cursor-pointer">
            <div className="h-[2px] bg-gray-700 rounded"></div>
            <div className="h-[2px] bg-gray-700 rounded"></div>
            <div className="h-[2px] bg-gray-700 rounded"></div>
          </div>
          {/* Logo */}
          <div className="flex items-center gap-2">
            <span className="text-xl font-bold tracking-wide text-gray-900">RELX 悦刻</span>
          </div>
        </div>

        {/* Nav Tabs */}
        <nav className="flex items-center gap-1 ml-8">
          {topNavTabs.map((tab) => (
            <div
              key={tab.key}
              className={`px-5 py-3 cursor-pointer text-sm transition-colors relative ${
                activeTab === tab.key
                  ? 'text-blue-600 font-medium'
                  : 'text-gray-600 hover:text-gray-900'
              }`}
              onClick={() => setActiveTab(tab.key)}
            >
              {tab.label}
              {activeTab === tab.key && (
                <div className="absolute bottom-0 left-0 right-0 h-[2px] bg-blue-600 rounded-t"></div>
              )}
            </div>
          ))}
        </nav>

        {/* Search & Right icons */}
        <div className="ml-auto flex items-center gap-4">
          <Input
            prefix={<SearchOutlined className="text-gray-400" />}
            placeholder="搜索应用"
            value={searchValue}
            onChange={(e) => setSearchValue(e.target.value)}
            className="w-56 rounded-lg"
            allowClear
          />
          <button className="text-gray-500 hover:text-gray-700">
            <SearchOutlined />
          </button>
          <div className="w-px h-5 bg-gray-300"></div>
          <button className="text-gray-500 hover:text-gray-700">
            <BellOutlined className="text-lg" />
          </button>
          <div className="w-8 h-8 rounded-full bg-gradient-to-br from-blue-400 to-blue-600 flex items-center justify-center text-white">
            <UserOutlined />
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 p-6 overflow-auto">
        {/* Welcome + Task Row */}
        <div className="grid grid-cols-12 gap-6 mb-6">
          {/* Welcome Banner */}
          <div className="col-span-7 relative overflow-hidden rounded-lg bg-gradient-to-r from-blue-500 via-blue-600 to-blue-400 p-6 text-white">
            {/* Decorative shapes */}
            <div className="absolute -right-10 -top-10 w-48 h-48 rounded-full bg-white/10"></div>
            <div className="absolute right-20 -bottom-8 w-32 h-32 rounded-full bg-white/10"></div>
            <div className="absolute -right-20 top-10 w-24 h-24 rounded-full bg-white/5"></div>
            <div className="relative z-10">
              <h2 className="text-xl font-semibold mb-2">欢迎登录TiCampus平台, 李山</h2>
              <p className="text-sm text-blue-100">{dateStr}，当前时间 {timeStr}</p>
            </div>
          </div>

          {/* Task Approval */}
          <div className="col-span-5 relative rounded-lg bg-white p-6 shadow-sm border border-gray-100 overflow-hidden">
            {/* Background clock illustration */}
            <div className="absolute right-0 top-0 w-40 h-full flex items-center justify-center opacity-20">
              <svg viewBox="0 0 200 200" className="w-36 h-36">
                <circle cx="100" cy="100" r="80" fill="none" stroke="#1890ff" strokeWidth="2"/>
                <circle cx="100" cy="100" r="5" fill="#1890ff"/>
                <line x1="100" y1="100" x2="100" y2="45" stroke="#1890ff" strokeWidth="3" strokeLinecap="round"/>
                <line x1="100" y1="100" x2="140" y2="115" stroke="#1890ff" strokeWidth="2" strokeLinecap="round"/>
              </svg>
            </div>
            {/* Geometric bg shapes */}
            <div className="absolute right-0 top-0 bottom-0 w-1/3 bg-gradient-to-l from-blue-50/60 to-transparent"></div>
            <div className="absolute right-4 top-4 w-20 h-20 border border-blue-200/40 rotate-45"></div>
            <div className="absolute right-12 bottom-4 w-16 h-16 border border-blue-200/30 rotate-12"></div>

            <div className="relative z-10">
              <h3 className="text-base font-semibold text-gray-800 mb-4">任务审批</h3>
              <div className="flex gap-6">
                {taskStats.map((stat) => (
                  <div key={stat.key} className="text-center">
                    <div className="text-xl font-semibold" style={{ color: stat.color }}>
                      {stat.value}
                    </div>
                    <div className="text-xs text-gray-500 mt-1">{stat.label}</div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>

        {/* Common Apps */}
        <div className="bg-white rounded-lg p-6 shadow-sm border border-gray-100">
          <div className="flex items-center justify-between mb-5">
            <h3 className="text-base font-semibold text-gray-800">常用应用</h3>
            <span className="text-sm text-blue-600 hover:underline cursor-pointer">查看更多</span>
          </div>

          <div className="grid grid-cols-12 gap-6">
            {commonApps.map((app) => (
              <div
                key={app.id}
                className="col-span-2 flex flex-col items-center gap-2 cursor-pointer group"
                onClick={() => handleAppClick(app)}
              >
                <div
                  className={`w-14 h-14 rounded-full flex items-center justify-center text-2xl text-white shadow-sm transition-transform group-hover:scale-110 group-hover:shadow-md ${app.color}`}
                >
                  {app.icon}
                </div>
                <span className="text-xs text-gray-700 group-hover:text-blue-600 transition-colors">
                  {app.name}
                </span>
              </div>
            ))}
            {/* Add App */}
            <div className="col-span-2 flex flex-col items-center gap-2 cursor-pointer">
              <div className="w-14 h-14 rounded-full flex items-center justify-center text-2xl text-blue-500 border-2 border-dashed border-blue-400 bg-blue-50 hover:bg-blue-100 transition-colors">
                +
              </div>
              <span className="text-xs text-blue-500">添加应用</span>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
};

export default Workbench;
