import { useState } from 'react';
import DynamicMonitorSidebar from './DynamicMonitorSidebar';
import DynamicMonitorDashboard from './DynamicMonitorDashboard';
import TempHumMonitor from './TempHumMonitor';
import WaterLeakMonitor from './WaterLeakMonitor';
import { BellOutlined, UserOutlined } from '@ant-design/icons';

const DynamicMonitor = () => {
  const [selectedKey, setSelectedKey] = useState('dashboard');

  const handleSelect = (key: string) => {
    setSelectedKey(key);
  };

  const renderContent = () => {
    switch (selectedKey) {
      case 'dashboard':
        return <DynamicMonitorDashboard />;
      case 'tempHum':
        return <TempHumMonitor />;
      case 'waterLeak':
        return <WaterLeakMonitor />;
      default:
        return (
          <div className="flex-1 flex items-center justify-center text-gray-400">
            <div className="text-center">
              <div className="text-2xl font-light text-gray-500 mb-2">李山，欢迎登录</div>
              <div className="text-sm text-gray-400">上午好，今天是2026年，08月31日，星期一</div>
            </div>
          </div>
        );
    }
  };

  const topBarTitle = (() => {
    if (selectedKey === 'dashboard') return '动环看板';
    const titleMap: Record<string, string> = {
      tempHum: '温湿度监控',
      waterLeak: '漏水监测',
      smoke: '烟雾监测',
      battery: '蓄电池单体',
      ups3: '三相UPS',
      power3: '三相电量',
      pdu: '智能PDU',
      alertRecord: '告警记录',
      alertRule: '告警规则',
      deviceList: '设备管理',
      areaLocation: '区域位置',
    };
    return titleMap[selectedKey] || '动环监测';
  })();

  return (
    <div className="h-screen flex bg-gray-50">
      {/* Sidebar */}
      <DynamicMonitorSidebar selectedKey={selectedKey} onSelect={handleSelect} />

      {/* Main area */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Top bar */}
        <header className="h-12 bg-white border-b border-gray-200 flex items-center justify-between px-4">
          <div className="text-sm font-medium text-gray-700">{topBarTitle}</div>
          <div className="flex items-center gap-4">
            <button className="text-gray-500 hover:text-gray-700">
              <BellOutlined />
            </button>
            <span className="text-sm text-gray-600">雾芯科技</span>
            <div className="w-7 h-7 rounded-full bg-gradient-to-br from-blue-400 to-blue-600 flex items-center justify-center text-white text-xs">
              <UserOutlined />
            </div>
          </div>
        </header>

        {/* Content */}
        <main className="flex-1 overflow-auto">{renderContent()}</main>
      </div>
    </div>
  );
};

export default DynamicMonitor;
